draw:
var k = 8.99e9, g = 9.8;
var q = p.q * 1e-9, m = p.m * 1e-3, L = p.L;

// solve sin(th)^2 * tan(th) = k q^2 / (4 L^2 m g) by bisection
var Kc = k * q * q / (4 * L * L * m * g);
var lo = 1e-6, hi = 1.5533, mid = 0;
for (var i = 0; i < 60; i++) {
  mid = 0.5 * (lo + hi);
  var f = Math.sin(mid) * Math.sin(mid) * Math.tan(mid) - Kc;
  if (f > 0) hi = mid; else lo = mid;
}
var th = mid;
var sep = 2 * L * Math.sin(th);

// gentle wobble so the reader sees it is an equilibrium
var wob = 0.05 * th * Math.cos(5 * t) * Math.exp(-(t % 9) * 0.5);
var thA = th + wob, thB = th + wob;

var px = W / 2, py = H * 0.1;
var scale = (H * 0.72) / L;
var ax = px - L * Math.sin(thA) * scale, ay = py + L * Math.cos(thA) * scale;
var bx = px + L * Math.sin(thB) * scale, by = py + L * Math.cos(thB) * scale;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// ceiling
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(W * 0.3, py); ctx.lineTo(W * 0.7, py); ctx.stroke();

// vertical reference
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + L * scale); ctx.stroke();
ctx.setLineDash([]);

// threads
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(ax, ay); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();

// balls
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(ax, ay, 8, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(bx, by, 8, 0, Math.PI * 2); ctx.fill();

// separation marker
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(ax, ay + 20); ctx.lineTo(bx, by + 20); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("r = " + sep.toFixed(3) + " m", (ax + bx) / 2, ay + 36);

// angle label
ctx.fillText("theta = " + (th * 180 / Math.PI).toFixed(1) + " deg", px + W * 0.20, py + 26);

var F = k * q * q / (sep * sep);
ctx.textAlign = "left";
ctx.fillText("Coulomb push = " + F.toExponential(2) + " N", W * 0.04, H * 0.95);
ctx.fillText("weight = " + (m * g).toExponential(2) + " N", W * 0.04, H * 0.86);

out.note = "separation " + sep.toFixed(4) + " m, angle " + (th * 180 / Math.PI).toFixed(2) +
  " deg, tan(theta) = " + Math.tan(th).toFixed(4);
